<script lang="ts">
 import {onMount} from 'svelte';
 import {page} from '$app/stores';
 import StyleLibrary from '$lib/components/StyleLibrary.svelte';
 import {api} from '$lib/api';
 let settings:any={},models:any[]=[],requestLog:any[]=[];
 let provider='anthropic',apiKey='',baseUrl='',modelWrite='',modelStruct='',budget=32000,styleBudget=2000,tempWrite=.9,tempStruct=0,testStatus='';
 let prompts:Array<{id:string;defaultValue:string;value:string;modified:boolean}>=[],selectedPrompt='preamble',promptDraft='',promptBusy=false;
 $: currentPrompt=prompts.find(p=>p.id===selectedPrompt);
 const promptLabel=(id:string)=>id.startsWith('flow.')?'Writing action · '+id.slice(5).replaceAll('_',' '):({preamble:'Shared writing instructions',conversation:'Conversation without card context',structure:'Card structuring',digest:'Continuity summaries',json:'JSON response instructions',connection:'Connection test'} as Record<string,string>)[id]||id;
 function selectPrompt(){promptDraft=prompts.find(p=>p.id===selectedPrompt)?.value||'';}
 async function loadPrompts(){prompts=await api('/settings/prompts');selectPrompt();}
 async function saveSelectedPrompt(reset=false){promptBusy=true;await safely(async()=>{prompts=await api('/settings/prompts','PUT',{id:selectedPrompt,value:reset?null:promptDraft});selectPrompt();notice=reset?'Prompt reset to default':'Prompt saved';});promptBusy=false;}
 async function resetAllPrompts(){promptBusy=true;await safely(async()=>{prompts=await api('/settings/prompts','DELETE');selectPrompt();notice='All prompts reset to defaults';});promptBusy=false;}
 let loading=true,busy=false,error='',notice='';
 $: requestedReturn=$page.url.searchParams.get('returnTo')||'/';
 $: returnTo=/^\/n\/[^?#]+(?:\?[^#]*)?$/.test(requestedReturn)?requestedReturn:'/';
 async function safely(fn:()=>Promise<any>){error='';notice='';try{return await fn();}catch(e:any){error=e.message;}}
 onMount(()=>{const theme=localStorage.getItem('novel-theme');if(theme)document.documentElement.dataset.theme=theme;void load();});
 async function load(){await safely(async()=>{settings=await api('/settings');provider=settings.provider||'anthropic';baseUrl=settings.baseUrl||'';modelWrite=settings.modelWrite||'';modelStruct=settings.modelStruct||'';budget=settings.budget||32000;styleBudget=settings.styleBudget||2000;tempWrite=settings.temps?.write??.9;tempStruct=settings.temps?.struct??0;await Promise.all([loadModels(),loadRequestLog(),loadPrompts()]);});loading=false;}
 async function loadRequestLog(){await safely(async()=>{requestLog=await api('/settings/requests');});}
 async function loadModels(){try{const value=await api(`/settings/models?provider=${provider}&baseUrl=${encodeURIComponent(baseUrl)}`);models=Array.isArray(value)?value:value.models||[];}catch{models=[];}}
 const settingsBody=()=>({provider,...(apiKey?{apiKey}:{}),...(baseUrl?{baseUrl}:{}),modelWrite,modelStruct,budget:Number(budget),styleBudget:Number(styleBudget),temps:{write:Number(tempWrite),struct:Number(tempStruct)}});
 async function saveSettings(){busy=true;await safely(async()=>{settings=await api('/settings','PUT',settingsBody());apiKey='';notice='Settings saved';});busy=false;}
 async function testConnection(){busy=true;testStatus='Testing…';try{const result=await api('/settings/test','POST',settingsBody());testStatus=result.ok?'Connected. Both models respond.':result.write?.msg||result.struct?.msg||result.error||'Connection failed';}catch(e:any){testStatus=e.message;}finally{await loadRequestLog();busy=false;}}
</script>
<svelte:head><title>Settings · Reefnote</title></svelte:head>
<main class="settings-page"><div class="settings-content"><a class="settings-back" href={returnTo}>← Back to Reefnote</a>
{#if error}<p role="alert" class="settings-message danger">{error}</p>{/if}
{#if notice}<p role="status" class="settings-message">{notice}</p>{/if}
{#if loading}<p role="status">Loading settings…</p>{:else}<section class="settings-panel dlg"><h1>Settings</h1><p class="lead">Bring your own co-writer.</p><label for="provider">Provider</label><select id="provider" bind:value={provider} on:change={loadModels}>{#each [['anthropic','Anthropic'],['openai','OpenAI'],['google','Google Gemini'],['openrouter','OpenRouter'],['ollama','Ollama (local)'],['openai_compatible','OpenAI-compatible']] as [value,label]}<option {value}>{label}</option>{/each}</select>{#if provider!=='ollama'}<label for="key">API key {settings.hasKey?'(saved; leave blank to keep)':''}</label><input id="key" type="password" autocomplete="new-password" bind:value={apiKey}/>{:else}<p class="help">No key needed for a local Ollama server.</p>{/if}{#if ['ollama','openai_compatible','openrouter'].includes(provider)}<label for="baseurl">Base URL</label><input id="baseurl" bind:value={baseUrl} placeholder={provider==='ollama'?'http://localhost:11434':''} on:blur={loadModels}/>{/if}<div class="two"><div><label for="writing">Writing model</label><input id="writing" list="models" bind:value={modelWrite} placeholder="Enter or choose a model"/></div><div><label for="structuring">Structuring model</label><input id="structuring" list="models" bind:value={modelStruct} placeholder="Enter or choose a model"/></div></div><datalist id="models">{#each models as m}<option value={m.id||m}></option>{/each}</datalist><p class="help">Writing model drafts prose and ideas. Structuring model turns responses into card suggestions; a smaller, cheaper model is fine.</p><details><summary>Advanced</summary><label for="budget">Context budget (tokens)</label><input id="budget" type="number" min="1000" bind:value={budget}/><label for="style-budget">Style allocation (tokens, soft limit)</label><input id="style-budget" type="number" min="100" max="20000" bind:value={styleBudget}/><p class="help">Samples are shortened first. Required rules and notes must fit within the total context budget.</p><div class="two"><div><label for="tempwrite">Writing temperature</label><input id="tempwrite" type="number" min="0" max="2" step="0.1" bind:value={tempWrite}/></div><div><label for="tempstruct">Structuring temperature</label><input id="tempstruct" type="number" min="0" max="2" step="0.1" bind:value={tempStruct}/></div></div></details><p class="help" aria-live="polite">{testStatus}</p><div class="foot"><button class="btn ghost" disabled={busy} on:click={testConnection}>Test connection</button><a class="btn ghost" href={returnTo}>Cancel</a><button class="btn" disabled={busy} on:click={saveSettings}>Save settings</button></div></section><section class="settings-panel dlg prompt-editor"><h2>AI prompts</h2><p class="help">Edit the instructions used by the AI. Saved prompts apply to future requests and remain saved when Reefnote restarts. Card selection, conversation history, and other request context are managed by Reefnote.</p><label for="prompt-select">Prompt</label><select id="prompt-select" bind:value={selectedPrompt} on:change={selectPrompt} disabled={promptBusy}>{#each prompts as prompt}<option value={prompt.id}>{promptLabel(prompt.id)}{prompt.modified?' · Modified':''}</option>{/each}</select><label for="prompt-text">Instructions {currentPrompt?.modified?'(modified)':'(default)'}</label><textarea id="prompt-text" class="prompt-text" bind:value={promptDraft} disabled={promptBusy} spellcheck="false"></textarea><details><summary>View default instructions</summary><pre>{currentPrompt?.defaultValue}</pre></details><div class="foot"><button class="btn ghost" disabled={promptBusy} on:click={resetAllPrompts}>Reset all prompts</button><button class="btn ghost" disabled={promptBusy} on:click={()=>saveSelectedPrompt(true)}>Reset this prompt</button><button class="btn" disabled={promptBusy||!promptDraft.trim()||promptDraft===currentPrompt?.value} on:click={()=>saveSelectedPrompt()}>Save prompt</button></div></section><section class="settings-panel dlg"><StyleLibrary manager={true}/></section><section class="settings-panel dlg request-log"><h2>LLM request log</h2><p class="help">Latest 200 requests, including writing, structuring, summaries and tests. Tokens are reported by the provider; — means unavailable. Latency measures the full request.</p><button class="btn ghost" on:click={loadRequestLog}>Refresh log</button><div class="request-log-scroll"><table><thead><tr><th>Time / model</th><th>Input</th><th>Output</th><th>Latency</th><th>Status</th></tr></thead><tbody>{#each requestLog as request}<tr><td>{new Date(request.started_at).toLocaleString()}<br/>{request.provider} · {request.model}</td><td>{request.tokens_in??'—'}</td><td>{request.tokens_out??'—'}</td><td>{(request.latency_ms/1000).toFixed(2)}s</td><td>{request.status}</td></tr>{:else}<tr><td colspan="5">No requests logged yet.</td></tr>{/each}</tbody></table></div>
</section>{/if}</div></main>
<style>
 .settings-page{height:100dvh;overflow:auto;padding:32px 24px 64px}
 .settings-content{max-width:960px;margin:0 auto}
 .settings-back{display:inline-block;margin-bottom:24px;color:var(--accent);text-decoration:none}
 .settings-panel{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:28px 32px;margin-bottom:24px}
 h1{font:500 36px var(--serif);margin:0;border-bottom:1.5px solid var(--rule);padding-bottom:12px}
 .settings-message{padding:12px 16px;background:var(--soft);border:1px solid var(--line);border-radius:6px}
 .foot a{text-decoration:none}
 .prompt-editor .prompt-text{min-height:280px;font:14px/1.6 var(--ui);margin-bottom:16px}
 .prompt-editor pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.6 var(--ui);padding:16px;background:var(--soft);border-radius:6px}
 .request-log{margin-top:0}
 .request-log-scroll{max-height:520px}
 @media(max-width:600px){.settings-page{padding:20px 12px 40px}.settings-panel{padding:22px 18px}.settings-panel :global(.two){grid-template-columns:1fr}.settings-panel :global(.foot){flex-wrap:wrap}}
</style>
